begin;

-- Keep the two-argument legacy RPC intact. HTTP handlers use this overload and
-- supply cryptographically random promo candidates generated by Node.js.
create or replace function public.redeem_reward(
    p_user_id uuid, p_reward_id uuid, p_promo_codes text[]
)
returns jsonb
language plpgsql volatile security invoker set search_path = ''
as $$
declare
    v_reward public.rewards%rowtype;
    v_balance bigint;
    v_redemption_id uuid := gen_random_uuid();
    v_promo_code text;
    v_inserted boolean := false;
    v_pro_until timestamptz;
    v_now timestamptz;
begin
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception using errcode = 'P0001', message = 'unsupported_isolation_level';
    end if;
    if p_user_id is null or p_reward_id is null then
        raise exception using errcode = 'P0001', message = 'validation_error';
    end if;
    perform 1 from public.profiles where id = p_user_id for update;
    if not found then
        raise exception using errcode = 'P0001', message = 'validation_error';
    end if;
    v_now := clock_timestamp();
    select * into v_reward from public.rewards where id = p_reward_id for share;
    if not found then
        raise exception using errcode = 'P0001', message = 'reward_not_found';
    end if;
    if not v_reward.active then
        raise exception using errcode = 'P0001', message = 'reward_inactive';
    end if;
    v_balance := public.coin_balance(p_user_id);
    if v_balance < v_reward.cost_coins then
        raise exception using errcode = 'P0001', message = 'not_enough_coins',
            detail = (v_reward.cost_coins - v_balance)::text;
    end if;

    if v_reward.kind = 'partner_product' then
        if p_promo_codes is null or cardinality(p_promo_codes) not between 1 and 128
            or array_position(p_promo_codes, null) is not null
            or exists (select 1 from unnest(p_promo_codes) code
                where code !~ '^SHOWUP-[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{6}$') then
            raise exception using errcode = 'P0001', message = 'validation_error';
        end if;
        foreach v_promo_code in array p_promo_codes loop
            insert into public.redemptions(id, user_id, reward_id, coins_spent, promo_code)
            values (v_redemption_id, p_user_id, p_reward_id, v_reward.cost_coins, v_promo_code)
            on conflict (promo_code) do nothing;
            if found then v_inserted := true; exit; end if;
        end loop;
        if not v_inserted then
            raise exception using errcode = 'P0001', message = 'promo_code_exhausted';
        end if;
    else
        insert into public.redemptions(id, user_id, reward_id, coins_spent)
        values (v_redemption_id, p_user_id, p_reward_id, v_reward.cost_coins);
    end if;

    insert into public.coin_ledger(user_id, amount, reason, ref_id)
    values (p_user_id, -v_reward.cost_coins, 'reward_redemption', v_redemption_id::text);
    if v_reward.kind = 'pro_month' then
        insert into public.subscriptions as existing(user_id, plan, source, status, current_period_end)
        values (p_user_id, 'pro_monthly', 'coin_redemption', 'active', v_now + interval '30 days')
        on conflict (user_id) do update set
            plan = excluded.plan, source = excluded.source, status = excluded.status,
            current_period_end = greatest(existing.current_period_end, v_now) + interval '30 days'
        returning current_period_end into v_pro_until;
        update public.profiles set is_pro = true where id = p_user_id;
        return jsonb_build_object('balance', v_balance - v_reward.cost_coins, 'pro_until', v_pro_until);
    end if;
    return jsonb_build_object('balance', v_balance - v_reward.cost_coins, 'promo_code', v_promo_code);
end;
$$;
revoke all on function public.redeem_reward(uuid, uuid, text[]) from public, anon, authenticated;
grant execute on function public.redeem_reward(uuid, uuid, text[]) to service_role;

create or replace function public.mock_subscribe(p_user_id uuid)
returns jsonb
language plpgsql volatile security invoker set search_path = ''
as $$
declare v_now timestamptz; v_pro_until timestamptz;
begin
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception using errcode = 'P0001', message = 'unsupported_isolation_level';
    end if;
    perform 1 from public.profiles where id = p_user_id for update;
    if not found then
        raise exception using errcode = 'P0001', message = 'validation_error';
    end if;
    v_now := clock_timestamp();
    select current_period_end into v_pro_until from public.subscriptions where user_id = p_user_id;
    if v_pro_until is null or v_pro_until <= v_now then
        insert into public.subscriptions as existing(user_id, plan, source, status, current_period_end)
        values (p_user_id, 'pro_monthly', 'mock_payment', 'active', v_now + interval '30 days')
        on conflict (user_id) do update set
            plan = excluded.plan, source = excluded.source, status = excluded.status,
            current_period_end = excluded.current_period_end
        returning current_period_end into v_pro_until;
    end if;
    update public.profiles set is_pro = true where id = p_user_id;
    return jsonb_build_object('is_pro', true, 'pro_until', v_pro_until);
end;
$$;
revoke all on function public.mock_subscribe(uuid) from public, anon, authenticated;
grant execute on function public.mock_subscribe(uuid) to service_role;

create unique index if not exists partner_sales_redemption_once on public.partner_sales(redemption_id);

create or replace function public.simulate_partner_purchase(
    p_user_id uuid, p_redemption_id uuid, p_amount_cents integer
)
returns jsonb
language plpgsql volatile security invoker set search_path = ''
as $$
declare
    v_partner_id uuid; v_kind text; v_commission_pct numeric;
    v_commission_cents integer; v_sale_id uuid;
begin
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception using errcode = 'P0001', message = 'unsupported_isolation_level';
    end if;
    if p_amount_cents is null or p_amount_cents < 0 then
        raise exception using errcode = 'P0001', message = 'validation_error';
    end if;
    perform 1 from public.profiles where id = p_user_id for update;
    if not found then
        raise exception using errcode = 'P0001', message = 'redemption_not_found';
    end if;
    select r.partner_id, r.kind into v_partner_id, v_kind
    from public.redemptions d join public.rewards r on r.id = d.reward_id
    where d.id = p_redemption_id and d.user_id = p_user_id
    for share of d, r;
    if not found then
        raise exception using errcode = 'P0001', message = 'redemption_not_found';
    end if;
    if v_kind <> 'partner_product' then
        raise exception using errcode = 'P0001', message = 'validation_error';
    end if;
    select commission_pct into v_commission_pct from public.partners where id = v_partner_id for share;
    -- PostgreSQL numeric arithmetic preserves fractional percentages exactly.
    v_commission_cents := floor(p_amount_cents::numeric * v_commission_pct / 100)::integer;
    insert into public.partner_sales(partner_id, redemption_id, amount_cents, commission_cents)
    values (v_partner_id, p_redemption_id, p_amount_cents, v_commission_cents)
    on conflict (redemption_id) do nothing returning id into v_sale_id;
    if not found then
        raise exception using errcode = 'P0001', message = 'already_purchased';
    end if;
    return jsonb_build_object('sale_id', v_sale_id, 'amount_cents', p_amount_cents, 'commission_cents', v_commission_cents);
end;
$$;
revoke all on function public.simulate_partner_purchase(uuid, uuid, integer) from public, anon, authenticated;
grant execute on function public.simulate_partner_purchase(uuid, uuid, integer) to service_role;

create or replace function public.partner_stats(p_partner_id uuid)
returns jsonb
language plpgsql stable security invoker set search_path = ''
as $$
declare v_result jsonb;
begin
    if not exists (select 1 from public.partners where id = p_partner_id) then
        raise exception using errcode = 'P0001', message = 'partner_not_found';
    end if;
    select jsonb_build_object(
        'sales_count', count(*),
        'revenue_cents', coalesce(sum(amount_cents), 0),
        'commission_cents', coalesce(sum(commission_cents), 0)
    ) into v_result from public.partner_sales where partner_id = p_partner_id;
    return v_result;
end;
$$;
revoke all on function public.partner_stats(uuid) from public, anon, authenticated;
grant execute on function public.partner_stats(uuid) to service_role;

commit;
notify pgrst, 'reload schema';
